std::vector<uint8_t> FixedSrc() {
  std::vector<uint8_t> v;
  const char* s = "the quick brown fox jumps over the lazy dog; ";
  for (int r = 0; r < 4; ++r) {
    for (int k = 0; k < 3; ++k) v.insert(v.end(), s, s + std::strlen(s));
    for (int b = 0; b < 256; b += 3) v.push_back(uint8_t(b));
  }
  return v;
}
